#!/usr/bin/env node
/**
 * Download the bundled qodercli binary used by the SDK when callers do not
 * provide options.pathToQoderCLIExecutable or QODERCLI_PATH.
 *
 * Environment variables:
 * - QODER_SKIP_DOWNLOAD=1|true: skip postinstall runtime downloads
 * - QODER_INSTALL_BUNDLED_CLI=1|true: download process fallback even when the packaged default runtime is Worker
 * - QODER_CLI_MIRROR: CDN base URL. Accepts .../qodercli, .../qodercli/dev, or .../releases
 * - QODER_WORKER_RUNTIME_URL: explicit worker runtime tgz URL override
 * - QODER_CLI_VERSION: override package.json qoderCliVersion
 * - QODER_CLI_SITE: download site. Supports global and cn
 * - QODER_CLI_PLATFORM: override target artifact, e.g. darwin-arm64, linux-x64-musl
 * - QODER_SKIP_CHECKSUM=1|true: skip .sha256 verification
 */

const { createHash } = require('crypto');
const { execFile } = require('child_process');
const fs = require('fs');
const http = require('http');
const https = require('https');
const os = require('os');
const path = require('path');

const GLOBAL_PROD_DOWNLOAD_BASE_URL =
  'https://download.qoder.com/qodercli/releases';
const GLOBAL_DEV_DOWNLOAD_BASE_URL =
  'https://qs-cli-dev.oss-cn-hangzhou.aliyuncs.com/qodercli/dev/releases';
const CN_PROD_DOWNLOAD_BASE_URL =
  'https://static.qoder.com.cn/qoder-cli-cn/releases';
const CN_DEV_DOWNLOAD_BASE_URL =
  'https://static.qoder.com.cn/qoder-cli-cn/dev/releases';
const LOG_PREFIX = '[@qoder-ai/qoder-agent-sdk]';

function isTruthy(value) {
  return value === '1' || value === 'true';
}

function getCliVersion() {
  const fromEnv = process.env.QODER_CLI_VERSION;
  if (fromEnv) return fromEnv.replace(/^v/, '');

  try {
    const packageJson = require('../package.json');
    const version = packageJson.qoderCliVersion ?? packageJson.version;
    if (!version) {
      throw new Error(
        'package.json must define "qoderCliVersion" or "version".',
      );
    }
    return String(version).replace(/^v/, '');
  } catch (error) {
    throw new Error(`Unable to resolve qodercli version: ${error.message}`);
  }
}

function isDevCliVersion(version) {
  return /(?:^|[.-])(alpha|dev|nightly)(?:[.-]|$)/i.test(version);
}

function normalizeCliSite(value) {
  const normalized = String(value).trim().toLowerCase();
  if (normalized === 'global') return 'global';
  if (normalized === 'cn') return 'cn';
  throw new Error(
    `Unsupported QODER_CLI_SITE "${value}". Supported: global, cn`,
  );
}

function getCliSite() {
  return normalizeCliSite(process.env.QODER_CLI_SITE ?? 'global');
}

function getCliArtifactPrefix(site = getCliSite()) {
  return site === 'cn' ? 'qoderclicn' : 'qodercli';
}

function getDownloadBaseUrl(version = getCliVersion()) {
  if (process.env.QODER_CLI_MIRROR) {
    return process.env.QODER_CLI_MIRROR;
  }
  const site = getCliSite();
  if (site !== 'global') {
    throw new Error(
      'QODER_CLI_SITE=cn requires QODER_CLI_MIRROR for CLI downloads.',
    );
  }
  if (isDevCliVersion(version)) {
    return GLOBAL_DEV_DOWNLOAD_BASE_URL;
  }
  return GLOBAL_PROD_DOWNLOAD_BASE_URL;
}

function getWorkerRuntimeDownloadBaseUrl(version = getCliVersion()) {
  if (process.env.QODER_CLI_MIRROR) {
    return process.env.QODER_CLI_MIRROR;
  }
  const site = getCliSite();
  if (site === 'cn') {
    return isDevCliVersion(version)
      ? CN_DEV_DOWNLOAD_BASE_URL
      : CN_PROD_DOWNLOAD_BASE_URL;
  }
  return isDevCliVersion(version)
    ? GLOBAL_DEV_DOWNLOAD_BASE_URL
    : GLOBAL_PROD_DOWNLOAD_BASE_URL;
}

function normalizeDownloadBaseUrl(baseUrl, version = getCliVersion()) {
  const trimmed = baseUrl.replace(/\/+$/, '');
  if (trimmed.endsWith(`/${version}`)) return trimmed;
  if (trimmed.endsWith('/releases')) return `${trimmed}/${version}`;
  return `${trimmed}/releases/${version}`;
}

function isLinuxMusl() {
  if (process.platform !== 'linux') return false;

  const report = process.report?.getReport?.();
  const glibcVersion = report?.header?.glibcVersionRuntime;
  if (glibcVersion) return false;

  try {
    const lddPath = fs.existsSync('/usr/bin/ldd') ? '/usr/bin/ldd' : 'ldd';
    const result = require('child_process').spawnSync(lddPath, ['--version'], {
      encoding: 'utf8',
    });
    const output = `${result.stdout ?? ''}${result.stderr ?? ''}`;
    return /musl/i.test(output);
  } catch {
    return true;
  }
}

function linuxX64HasAvx2() {
  try {
    const cpuInfo = fs.readFileSync('/proc/cpuinfo', 'utf8');
    return /^flags\s*:.*\bavx2\b/m.test(cpuInfo);
  } catch {
    return true;
  }
}

function normalizePlatformOverride(value) {
  const normalized = value.replace(/_/g, '-').replace(/-amd64(?=-|$)/, '-x64');
  const supported = new Set([
    'darwin-arm64',
    'darwin-x64',
    'linux-arm64',
    'linux-arm64-musl',
    'linux-x64',
    'linux-x64-baseline',
    'linux-x64-musl',
    'windows-x64',
  ]);

  if (!supported.has(normalized)) {
    throw new Error(
      `Unsupported QODER_CLI_PLATFORM "${value}". Supported: ${[...supported].join(', ')}`,
    );
  }
  return normalized;
}

function getPlatformTarget() {
  if (process.env.QODER_CLI_PLATFORM) {
    return normalizePlatformOverride(process.env.QODER_CLI_PLATFORM);
  }

  if (process.platform === 'darwin') {
    const arch = process.arch === 'arm64' ? 'arm64' : 'x64';
    return `darwin-${arch}`;
  }

  if (process.platform === 'win32') {
    if (process.arch !== 'x64') {
      throw new Error(`Unsupported Windows architecture: ${process.arch}`);
    }
    return 'windows-x64';
  }

  if (process.platform === 'linux') {
    if (process.arch === 'arm64') {
      return isLinuxMusl() ? 'linux-arm64-musl' : 'linux-arm64';
    }
    if (process.arch === 'x64') {
      if (isLinuxMusl()) return 'linux-x64-musl';
      return linuxX64HasAvx2() ? 'linux-x64' : 'linux-x64-baseline';
    }
  }

  throw new Error(`Unsupported platform: ${process.platform}/${process.arch}`);
}

function getArchiveExtension(target = getPlatformTarget()) {
  return target.startsWith('windows-') ? '.zip' : '.tar.gz';
}

function getArtifactName(target = getPlatformTarget()) {
  return `${getCliArtifactPrefix()}-${target}${getArchiveExtension(target)}`;
}

function getDownloadUrl() {
  const version = getCliVersion();
  const baseUrl = normalizeDownloadBaseUrl(
    getDownloadBaseUrl(version),
    version,
  );
  return `${baseUrl}/${getArtifactName()}`;
}

function getWorkerRuntimeArtifactName(site = getCliSite()) {
  return `${getCliArtifactPrefix(site)}-worker-runtime-universal.tgz`;
}

function hasWorkerRuntimeDownloadSiteOverride() {
  return Boolean(process.env.QODER_CLI_SITE || process.env.QODER_CLI_MIRROR);
}

function getManifestWorkerRuntime(manifest = readRuntimeManifest()) {
  const workerRuntime = manifest?.workerRuntime;
  return workerRuntime && typeof workerRuntime === 'object'
    ? workerRuntime
    : null;
}

function getManifestWorkerRuntimeDownloadUrl(manifest = readRuntimeManifest()) {
  const workerRuntime = getManifestWorkerRuntime(manifest);
  if (!workerRuntime || workerRuntime.packaged === true) return null;

  const candidates = [
    workerRuntime.url,
    workerRuntime.artifact?.url,
    workerRuntime.source?.url,
  ];
  const url = candidates.find(
    (candidate) => typeof candidate === 'string' && candidate.length > 0,
  );
  return url ?? null;
}

function getManifestWorkerRuntimeSha256(manifest = readRuntimeManifest()) {
  const workerRuntime = getManifestWorkerRuntime(manifest);
  if (!workerRuntime || workerRuntime.packaged === true) return null;

  const candidates = [
    workerRuntime.sha256,
    workerRuntime.artifact?.sha256,
    workerRuntime.source?.sha256,
  ];
  const checksum = candidates.find(
    (candidate) =>
      typeof candidate === 'string' &&
      /^[a-fA-F0-9]{64}$/.test(candidate.trim()),
  );
  return checksum ? checksum.trim().toLowerCase() : null;
}

function getWorkerRuntimeDownloadUrl() {
  if (process.env.QODER_WORKER_RUNTIME_URL) {
    return process.env.QODER_WORKER_RUNTIME_URL;
  }

  const manifestUrl = hasWorkerRuntimeDownloadSiteOverride()
    ? null
    : getManifestWorkerRuntimeDownloadUrl();
  if (manifestUrl) {
    return manifestUrl;
  }

  const version = getCliVersion();
  const baseUrl = normalizeDownloadBaseUrl(
    getWorkerRuntimeDownloadBaseUrl(version),
    version,
  );
  return `${baseUrl}/${getWorkerRuntimeArtifactName()}`;
}

function getWorkerRuntimeExpectedSha256(url = getWorkerRuntimeDownloadUrl()) {
  const manifestUrl = getManifestWorkerRuntimeDownloadUrl();
  if (manifestUrl && manifestUrl === url) {
    return getManifestWorkerRuntimeSha256();
  }

  return null;
}

function getBundledDir() {
  return path.join(__dirname, '..', 'dist', '_bundled');
}

function getBundledCliPath() {
  const cliName = process.platform === 'win32' ? 'qodercli.exe' : 'qodercli';
  return path.join(getBundledDir(), cliName);
}

function getPackagedWorkerRuntimePath() {
  return path.join(
    __dirname,
    '..',
    'dist',
    '_worker',
    'qoder-worker-runtime.obf.mjs',
  );
}

function getPackagedWorkerRuntimeInfoPath() {
  return path.join(path.dirname(getPackagedWorkerRuntimePath()), 'runtime-info.json');
}

function hasPackagedWorkerRuntime() {
  return fs.existsSync(getPackagedWorkerRuntimePath());
}

function readPackagedWorkerRuntimeInfo() {
  const runtimeInfoPath = getPackagedWorkerRuntimeInfoPath();
  if (!fs.existsSync(runtimeInfoPath)) {
    return null;
  }
  try {
    const parsed = JSON.parse(fs.readFileSync(runtimeInfoPath, 'utf8'));
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch {
    return null;
  }
}

function isPackagedWorkerRuntimeCompatibleWithSite(site = getCliSite()) {
  if (!hasPackagedWorkerRuntime()) return false;
  if (process.env.QODER_WORKER_RUNTIME_URL) return false;

  const runtimeInfo = readPackagedWorkerRuntimeInfo();
  if (!runtimeInfo) return false;

  const expectedProductName = getCliArtifactPrefix(site);
  const buildInfo =
    runtimeInfo.build && typeof runtimeInfo.build === 'object'
      ? runtimeInfo.build
      : {};
  const actualProductName = buildInfo.productName;
  const actualSite = buildInfo.site;

  if (
    typeof actualProductName === 'string' &&
    actualProductName.length > 0 &&
    actualProductName !== expectedProductName
  ) {
    return false;
  }

  if (
    typeof actualSite === 'string' &&
    actualSite.length > 0 &&
    actualSite !== site
  ) {
    return false;
  }

  return true;
}

function getRuntimeManifestPath() {
  return path.join(__dirname, '..', 'dist', 'runtime-manifest.json');
}

function readRuntimeManifest() {
  const manifestPath = getRuntimeManifestPath();
  if (!fs.existsSync(manifestPath)) {
    return null;
  }
  try {
    const parsed = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch {
    return null;
  }
}

function getDefaultRuntimeTransport() {
  const manifest = readRuntimeManifest();
  return manifest?.defaultTransport === 'worker' ? 'worker' : 'process';
}

function shouldInstallWorkerRuntimeForDefaultWorker() {
  return (
    getDefaultRuntimeTransport() === 'worker' &&
    !isPackagedWorkerRuntimeCompatibleWithSite()
  );
}

function shouldSkipBundledCliDownloadForWorkerRuntime() {
  if (getDefaultRuntimeTransport() !== 'worker') return false;
  return !isTruthy(process.env.QODER_INSTALL_BUNDLED_CLI);
}

function requestUrl(url, redirectCount = 0) {
  return new Promise((resolve, reject) => {
    if (redirectCount > 5) {
      reject(new Error('Too many redirects'));
      return;
    }

    const client = url.startsWith('https:') ? https : http;
    const request = client.get(url, (response) => {
      if (
        response.statusCode === 301 ||
        response.statusCode === 302 ||
        response.statusCode === 307 ||
        response.statusCode === 308
      ) {
        const location = response.headers.location;
        if (!location) {
          reject(new Error('Redirect response missing location header'));
          return;
        }
        const nextUrl = location.startsWith('http')
          ? location
          : new URL(location, url).href;
        response.resume();
        resolve(requestUrl(nextUrl, redirectCount + 1));
        return;
      }

      resolve(response);
    });

    request.setTimeout(60_000, () => {
      request.destroy(new Error('Request timeout (60s)'));
    });
    request.on('error', reject);
  });
}

async function downloadFile(url, destPath) {
  console.log(`${LOG_PREFIX} Downloading: ${url}`);
  const response = await requestUrl(url);
  if (response.statusCode !== 200) {
    response.resume();
    throw new Error(`Download failed: HTTP ${response.statusCode}`);
  }

  await new Promise((resolve, reject) => {
    const totalSize = Number.parseInt(
      response.headers['content-length'] || '0',
      10,
    );
    let downloadedSize = 0;
    let lastProgress = 0;
    const file = fs.createWriteStream(destPath);

    response.on('data', (chunk) => {
      downloadedSize += chunk.length;
      if (totalSize > 0) {
        const progress = Math.floor((downloadedSize / totalSize) * 100);
        if (progress >= lastProgress + 10 || progress === 100) {
          lastProgress = progress;
          console.log(`${LOG_PREFIX} Download progress: ${progress}%`);
        }
      }
    });

    response.pipe(file);
    file.on('finish', () => file.close(resolve));
    file.on('error', (err) => {
      fs.rm(destPath, { force: true }, () => {});
      reject(err);
    });
    response.on('error', reject);
  });
}

async function downloadWithRetry(url, destPath, maxRetries = 2) {
  let lastError;
  for (let attempt = 0; attempt <= maxRetries; attempt += 1) {
    try {
      if (attempt > 0) {
        console.log(`${LOG_PREFIX} Retry attempt ${attempt}/${maxRetries}`);
      }
      await downloadFile(url, destPath);
      return;
    } catch (error) {
      lastError = error;
      console.error(`${LOG_PREFIX} Download failed: ${error.message}`);
      fs.rmSync(destPath, { force: true });
    }
  }
  throw lastError;
}

function parseSha256(text) {
  const match = text.match(/[a-fA-F0-9]{64}/);
  if (!match) {
    throw new Error('Invalid sha256 file: checksum not found');
  }
  return match[0].toLowerCase();
}

function sha256File(filePath) {
  const hash = createHash('sha256');
  hash.update(fs.readFileSync(filePath));
  return hash.digest('hex');
}

async function verifyChecksum(archiveUrl, archivePath, expectedSha256) {
  if (isTruthy(process.env.QODER_SKIP_CHECKSUM)) {
    console.log(
      `${LOG_PREFIX} QODER_SKIP_CHECKSUM is set, skipping checksum verification.`,
    );
    return;
  }

  if (expectedSha256) {
    const expected = String(expectedSha256).trim().toLowerCase();
    if (!/^[a-fA-F0-9]{64}$/.test(expected)) {
      throw new Error(`Invalid expected sha256: ${expectedSha256}`);
    }
    const actual = sha256File(archivePath);
    if (actual !== expected) {
      throw new Error(
        `Checksum verification failed. Expected ${expected}, actual ${actual}`,
      );
    }
    console.log(`${LOG_PREFIX} Checksum verified.`);
    return;
  }

  const checksumPath = `${archivePath}.sha256`;
  await downloadWithRetry(`${archiveUrl}.sha256`, checksumPath, 1);
  const expected = parseSha256(fs.readFileSync(checksumPath, 'utf8'));
  const actual = sha256File(archivePath);
  if (actual !== expected) {
    throw new Error(
      `Checksum verification failed. Expected ${expected}, actual ${actual}`,
    );
  }
  console.log(`${LOG_PREFIX} Checksum verified.`);
}

function execFilePromise(command, args, options = {}) {
  return new Promise((resolve, reject) => {
    execFile(command, args, options, (error, stdout, stderr) => {
      if (error) {
        reject(
          new Error(
            `${command} ${args.join(' ')} failed: ${error.message}${stderr ? `\n${stderr}` : ''}`,
          ),
        );
        return;
      }
      resolve(stdout);
    });
  });
}

function getPathApi(filePath) {
  return /^[a-zA-Z]:[\\/]/.test(filePath) ? path.win32 : path;
}

function getTarExtractInvocation(archivePath, destDir) {
  const pathApi = getPathApi(archivePath);
  const cwd = pathApi.dirname(archivePath);
  return {
    cwd,
    args: [
      '-xzf',
      pathApi.basename(archivePath),
      '-C',
      pathApi.relative(cwd, destDir) || '.',
    ],
  };
}

async function extractArchive(archivePath, destDir) {
  if (archivePath.endsWith('.tar.gz') || archivePath.endsWith('.tgz')) {
    const invocation = getTarExtractInvocation(archivePath, destDir);
    await execFilePromise('tar', invocation.args, { cwd: invocation.cwd });
    return;
  }

  if (archivePath.endsWith('.zip')) {
    if (process.platform === 'win32') {
      await execFilePromise('powershell', [
        '-NoProfile',
        '-Command',
        `Expand-Archive -Path ${JSON.stringify(archivePath)} -DestinationPath ${JSON.stringify(destDir)} -Force`,
      ]);
    } else {
      await execFilePromise('unzip', ['-o', archivePath, '-d', destDir]);
    }
    return;
  }

  throw new Error(`Unsupported archive format: ${archivePath}`);
}

function findCliBinary(dir, cliName) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isFile() && isCliBinaryName(entry.name, cliName)) return fullPath;
    if (entry.isDirectory()) {
      const nested = findCliBinary(fullPath, cliName);
      if (nested) return nested;
    }
  }
  return null;
}

function isCliBinaryName(fileName, cliName) {
  if (fileName === cliName) return true;
  const sourceNames = ['qodercli', 'qoderclicn'];
  if (process.platform === 'win32') {
    return sourceNames.some(
      (sourceName) =>
        fileName.toLowerCase() === `${sourceName}.exe` ||
        new RegExp(`^${sourceName}-.+\\.exe$`, 'i').test(fileName),
    );
  }
  return sourceNames.some(
    (sourceName) =>
      fileName === sourceName ||
      (new RegExp(`^${sourceName}-.+$`, 'i').test(fileName) &&
        !fileName.endsWith('.sha256')),
  );
}

function copyDirContents(srcDir, destDir) {
  fs.mkdirSync(destDir, { recursive: true });
  for (const entry of fs.readdirSync(srcDir, { withFileTypes: true })) {
    const srcPath = path.join(srcDir, entry.name);
    const destPath = path.join(destDir, entry.name);
    if (entry.isDirectory()) {
      copyDirContents(srcPath, destPath);
      continue;
    }
    if (!entry.isFile()) continue;
    fs.copyFileSync(srcPath, destPath);
    if (process.platform !== 'win32') {
      fs.chmodSync(destPath, 0o755);
    }
  }
}

function installExtractedContents(extractDir, bundledDir) {
  const cliName = process.platform === 'win32' ? 'qodercli.exe' : 'qodercli';
  const extractedCli = findCliBinary(extractDir, cliName);
  if (!extractedCli) {
    throw new Error(
      'CLI binary not found in extracted archive. Expected qodercli/qoderclicn or platform-suffixed variants.',
    );
  }

  const contentRoot = path.dirname(extractedCli);
  copyDirContents(contentRoot, bundledDir);

  const target = path.join(bundledDir, cliName);
  const copiedCli = path.join(bundledDir, path.basename(extractedCli));
  if (copiedCli !== target) {
    fs.copyFileSync(copiedCli, target);
  }
  if (process.platform !== 'win32') {
    fs.chmodSync(target, 0o755);
  }

  const files = fs.readdirSync(bundledDir);
  console.log(
    `${LOG_PREFIX} Copied ${files.length} file(s) to _bundled: ${files.join(', ')}`,
  );
  return target;
}

function findWorkerRuntimeRoot(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  const hasWorkerRuntime = entries.some(
    (entry) =>
      entry.isFile() &&
      (entry.name === 'qoder-worker-runtime.obf.mjs' ||
        entry.name === 'qoder-worker-runtime.mjs'),
  );
  if (hasWorkerRuntime) return dir;

  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const nested = findWorkerRuntimeRoot(path.join(dir, entry.name));
    if (nested) return nested;
  }
  return null;
}

function installExtractedWorkerRuntime(extractDir, workerDir) {
  const contentRoot = findWorkerRuntimeRoot(extractDir);
  if (!contentRoot) {
    throw new Error(
      'Worker runtime not found in extracted archive. Expected qoder-worker-runtime.obf.mjs or qoder-worker-runtime.mjs.',
    );
  }

  fs.rmSync(workerDir, { recursive: true, force: true });
  copyDirContents(contentRoot, workerDir);

  const obfuscatedRuntime = path.join(
    workerDir,
    'qoder-worker-runtime.obf.mjs',
  );
  const plainRuntime = path.join(workerDir, 'qoder-worker-runtime.mjs');
  const runtimePath = fs.existsSync(obfuscatedRuntime)
    ? obfuscatedRuntime
    : plainRuntime;
  if (!fs.existsSync(runtimePath)) {
    throw new Error(`Worker runtime copy failed: ${runtimePath}`);
  }

  const files = fs.readdirSync(workerDir);
  console.log(
    `${LOG_PREFIX} Copied ${files.length} file(s) to _worker: ${files.join(', ')}`,
  );
  return runtimePath;
}

async function installWorkerRuntimeFromDownload() {
  const url = getWorkerRuntimeDownloadUrl();
  const expectedSha256 = getWorkerRuntimeExpectedSha256(url);
  const tempDir = fs.mkdtempSync(
    path.join(os.tmpdir(), 'qoder-worker-runtime-'),
  );
  const archivePath = path.join(tempDir, path.basename(new URL(url).pathname));
  const extractDir = path.join(tempDir, 'extract');

  try {
    await downloadWithRetry(url, archivePath);
    await verifyChecksum(url, archivePath, expectedSha256);
    fs.mkdirSync(extractDir, { recursive: true });
    await extractArchive(archivePath, extractDir);
    return installExtractedWorkerRuntime(
      extractDir,
      path.dirname(getPackagedWorkerRuntimePath()),
    );
  } finally {
    fs.rmSync(tempDir, { recursive: true, force: true });
  }
}

async function main() {
  if (isTruthy(process.env.QODER_SKIP_DOWNLOAD)) {
    console.log(
      `${LOG_PREFIX} QODER_SKIP_DOWNLOAD is set, skipping runtime downloads.`,
    );
    return;
  }

  if (shouldInstallWorkerRuntimeForDefaultWorker()) {
    console.log(
      `${LOG_PREFIX} Package default runtime is Worker; downloading Worker runtime.`,
    );
    await installWorkerRuntimeFromDownload();
  }

  if (shouldSkipBundledCliDownloadForWorkerRuntime()) {
    console.log(
      `${LOG_PREFIX} Package default runtime is Worker; skipping bundled CLI binary download. Set QODER_INSTALL_BUNDLED_CLI=1 to install the process fallback as well.`,
    );
    return;
  }

  const bundledCliPath = getBundledCliPath();
  if (fs.existsSync(bundledCliPath)) {
    console.log(`${LOG_PREFIX} CLI binary already exists, skipping download.`);
    return;
  }

  const version = getCliVersion();
  const bundleName = getCliArtifactPrefix();
  const target = getPlatformTarget();
  const archiveName = getArtifactName(target);
  const downloadUrl = getDownloadUrl();
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'qoder-cli-'));
  const archivePath = path.join(tempDir, archiveName);
  const extractDir = path.join(tempDir, 'extract');

  console.log(
    `${LOG_PREFIX} Installing ${bundleName} ${version} for ${target}.`,
  );

  try {
    fs.mkdirSync(extractDir, { recursive: true });
    await downloadWithRetry(downloadUrl, archivePath);
    await verifyChecksum(downloadUrl, archivePath);
    await extractArchive(archivePath, extractDir);
    const installedPath = installExtractedContents(extractDir, getBundledDir());
    const stats = fs.statSync(installedPath);
    console.log(
      `${LOG_PREFIX} CLI binary installed: ${installedPath} (${(stats.size / 1024 / 1024).toFixed(2)} MB)`,
    );
  } catch (error) {
    console.error(
      `${LOG_PREFIX} ERROR: Failed to install bundled CLI: ${error.message}`,
    );
    console.error(
      `${LOG_PREFIX} Set QODER_SKIP_DOWNLOAD=1 to skip download and use a system qodercli.`,
    );
    process.exit(1);
  } finally {
    fs.rmSync(tempDir, { recursive: true, force: true });
  }
}

if (require.main === module) {
  main().catch((error) => {
    console.error(`${LOG_PREFIX} Unexpected error:`, error);
    process.exit(1);
  });
}

